import{_ as o,o as r,c as a,a5 as d}from"./chunks/framework.Cooo9kuv.js";const g=JSON.parse('{"title":"WordPress 登录地址重命名插件 — Rename Login","description":"","frontmatter":{"标题":"WordPress 登录地址重命名插件 — Rename Login","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["WordPress","wp-admin","多站点","安全防护","暴力破解防护","登录地址自定义","登录美化","登录隐藏"]},"headers":[],"relativePath":"md/wordpress主题插件/WordPress 登录地址重命名插件 — Rename Login.md","filePath":"md/wordpress主题插件/WordPress 登录地址重命名插件 — Rename Login.md"}'),n={name:"md/wordpress主题插件/WordPress 登录地址重命名插件 — Rename Login.md"};function t(s,e,c,i,p,l){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="wordpress-登录地址重命名插件-—-rename-login" tabindex="-1">WordPress 登录地址重命名插件 — Rename Login <a class="header-anchor" href="#wordpress-登录地址重命名插件-—-rename-login" aria-label="Permalink to &quot;WordPress 登录地址重命名插件 — Rename Login&quot;">​</a></h1><blockquote><p>将 WordPress 默认的 wp-admin 和 wp-login.php 登录入口重命名为自定义 URL，隐藏后台登录地址，有效防御暴力破解和恶意扫描。支持登录页自定义美化、未登录访问自动重定向、中英双语界面，兼容多站点网络。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：WordPress 5.8+<br><strong>PHP</strong>：&gt;= 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-29.png" alt=""></p><p>本插件用于隐藏 WordPress 默认的后台登录入口。默认情况下，任何访客都可以通过 <code>/wp-admin</code> 或 <code>/wp-login.php</code> 直接访问登录页面，这让网站暴露在暴力破解攻击和恶意扫描的风险之下。</p><p>插件通过 URL 拦截和重写机制，将默认登录入口替换为您自定义的地址（如 <code>/my-login</code>）。激活后，原有的 <code>wp-admin</code> 和 <code>wp-login.php</code> 将无法直接访问，未登录用户访问后台时会自动跳转到自定义登录页或您指定的页面。</p><p>插件同时提供了一个完全独立的自定义登录页模板，支持品牌色、渐变背景、Logo 图片、卡片尺寸等可视化定制，且不依赖任何 WordPress 主题样式，确保登录页外观始终统一可控。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="自定义登录地址" tabindex="-1">自定义登录地址 <a class="header-anchor" href="#自定义登录地址" aria-label="Permalink to &quot;自定义登录地址&quot;">​</a></h3><p>在 WordPress 后台「设置 → Rename Login」页面中，设置您专属的登录地址 slug（如 <code>login</code>、<code>admin-panel</code>、<code>secret-door</code>），插件自动完成以下工作：</p><p>— 注册自定义 Rewrite 规则，使 WordPress 识别并响应新的登录 URL；<br> — 拦截所有对 <code>wp-login.php</code> 和 <code>wp-admin</code>（未登录时）的直接访问，将其重定向到首页或指定页面；<br> — 过滤站点所有 URL 输出（<code>site_url</code>、<code>wp_redirect</code>、欢迎邮件等），将其中出现的 <code>wp-login.php</code> 自动替换为新地址；<br> — 登录地址 slug 变更时，自动刷新 Rewrite 规则，无需手动更新固定链接。</p><p>设置页面顶部实时显示当前有效的完整登录地址，方便确认和收藏。</p><h3 id="未登录访问自动重定向" tabindex="-1">未登录访问自动重定向 <a class="header-anchor" href="#未登录访问自动重定向" aria-label="Permalink to &quot;未登录访问自动重定向&quot;">​</a></h3><p>当未登录用户尝试访问 WordPress 后台（<code>/wp-admin/</code>）时，插件自动将其重定向。您可以选择两种处理方式：</p><p>— <strong>默认行为</strong>：跳转到自定义登录页面，并附带 <code>redirect_to</code> 参数，登录成功后自动回到目标页面；<br> — <strong>自定义重定向</strong>：在「重定向地址」字段填写一个路径（如 <code>404</code>），未登录用户访问后台时将跳转到该页面，完全不暴露登录入口的存在。</p><h3 id="登录页自定义美化" tabindex="-1">登录页自定义美化 <a class="header-anchor" href="#登录页自定义美化" aria-label="Permalink to &quot;登录页自定义美化&quot;">​</a></h3><p>启用「登录页美化」开关后，插件使用独立的自定义模板渲染登录页面，完全脱离 WordPress 默认的 <code>wp-login.php</code> 样式。可配置以下外观选项：</p><p>— <strong>主色调</strong>：控制登录按钮、输入框聚焦边框、勾选框等元素的主题色，默认为蓝色（<code>#2563eb</code>）；<br> — <strong>背景渐变</strong>：登录页背景支持双色渐变（起始色 + 结束色），可搭配网站品牌色系；<br> — <strong>自定义 Logo</strong>：上传或填写 Logo 图片 URL，替换默认的站点名称文字；Logo 支持设置固定宽度和高度，留空则自适应；<br> — <strong>卡片尺寸</strong>：登录表单白色卡片的宽度、最小高度和内边距均可自由调整，适配不同设计需求；<br> — <strong>响应式适配</strong>：模板内置移动端断点样式，在小屏幕设备上自动缩小内边距和卡片圆角。</p><p>自定义模板还内置了找回密码和重置密码的完整流程，均在美化后的页面中完成，不回退到默认 <code>wp-login.php</code> 界面。</p><h3 id="内置中英双语" tabindex="-1">内置中英双语 <a class="header-anchor" href="#内置中英双语" aria-label="Permalink to &quot;内置中英双语&quot;">​</a></h3><p>插件内置了完整的 PHP 翻译数组，无需 <code>.mo</code> / <code>.po</code> 翻译文件：</p><p>— 支持「自动」「中文」「English」三种语言模式；<br> — 自动模式下根据 WordPress 站点语言自动匹配；<br> — 后台设置页面顶部提供语言切换下拉框，即时生效；<br> — 所有前端文本（登录页标签、提示信息、错误消息）均根据当前语言设置动态输出。</p><h3 id="多站点网络兼容" tabindex="-1">多站点网络兼容 <a class="header-anchor" href="#多站点网络兼容" aria-label="Permalink to &quot;多站点网络兼容&quot;">​</a></h3><p>插件完整支持 WordPress 多站点网络：</p><p>— 网络管理员可在「网络设置」中配置全站默认登录地址 slug；<br> — 各子站点可在各自的「设置 → Rename Login」中独立覆盖；<br> — 卸载时自动清理所有子站点的插件选项数据，不留残留。</p><h3 id="_404-状态码自动修正" tabindex="-1">404 状态码自动修正 <a class="header-anchor" href="#_404-状态码自动修正" aria-label="Permalink to &quot;404 状态码自动修正&quot;">​</a></h3><p>WordPress 在无法匹配到真实页面时会将请求标记为 404。插件通过多层防护机制确保自定义登录地址始终返回 200 状态码：</p><p>— <code>parse_request</code> 阶段提前识别登录请求并清除 404 标记；<br> — <code>status_header</code> 过滤器拦截后端即将发出的 404 状态头并修正为 200；<br> — 模板模式下直接设置正确的 HTTP 缓存头（<code>no-store, no-cache, must-revalidate</code>）。</p><h3 id="安全机制" tabindex="-1">安全机制 <a class="header-anchor" href="#安全机制" aria-label="Permalink to &quot;安全机制&quot;">​</a></h3><p>— 插件登录地址 slug 自动过滤 WordPress 保留路径（如 <code>wp-admin</code>、<code>wp-login</code> 及所有公共查询变量），防止冲突；<br> — 登录页模板添加 <code>noindex,nofollow,noarchive</code> 元标签，避免搜索引擎收录登录页面；<br> — 阻止 WordPress 对 <code>/wp-signup</code> 和 <code>/wp-activate</code> 的未授权访问（非多站点环境）。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>rename_login</code> 文件夹上传至网站 <code>wp-content/plugins/</code> 目录，进入 WordPress 后台「插件」页面，找到「Rename Login | 登录地址重命名」并点击启用。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-28.png" alt=""></p><h3 id="第二步-配置登录地址" tabindex="-1">第二步：配置登录地址 <a class="header-anchor" href="#第二步-配置登录地址" aria-label="Permalink to &quot;第二步：配置登录地址&quot;">​</a></h3><p>进入后台「设置 → Rename Login」页面：</p><p>— 在「登录地址」输入框中填写您想要的自定义 slug（如 <code>my-login</code>），页面顶部会实时显示变更后的完整 URL；<br> — 保存设置后，请务必收藏或牢记新的登录地址，因为原有的 <code>wp-admin</code> 和 <code>wp-login.php</code> 将无法直接访问；<br> — 如果新地址访问出现 404，点击页面上的「打开固定链接设置」按钮，在固定链接页面点击一次「保存更改」即可。</p><h3 id="第三步-配置重定向地址-可选" tabindex="-1">第三步：配置重定向地址（可选） <a class="header-anchor" href="#第三步-配置重定向地址-可选" aria-label="Permalink to &quot;第三步：配置重定向地址（可选）&quot;">​</a></h3><p>— 在「重定向地址」输入框中填写一个站点路径（如 <code>404</code>），未登录用户访问后台时将跳转到该页面；<br> — 留空则跳转到新的自定义登录页面。</p><h3 id="第四步-启用登录页美化-可选" tabindex="-1">第四步：启用登录页美化（可选） <a class="header-anchor" href="#第四步-启用登录页美化-可选" aria-label="Permalink to &quot;第四步：启用登录页美化（可选）&quot;">​</a></h3><p>— 打开「登录页美化」模块的开关；<br> — 按需调整主色调、背景渐变色、自定义 Logo 等外观选项；<br> — 保存后访问新的登录地址即可看到美化效果。</p><h3 id="后续维护" tabindex="-1">后续维护 <a class="header-anchor" href="#后续维护" aria-label="Permalink to &quot;后续维护&quot;">​</a></h3><p>— 您可以随时回到设置页面修改登录地址 slug，插件会自动刷新 Rewrite 规则；<br> — 如果忘记自定义登录地址，可通过 SFTP/FTP 或主机文件管理器删除插件目录 <code>/wp-content/plugins/rename_login</code>，网站将恢复默认登录入口；<br> — 停用插件后所有自定义设置会被保留，重新激活时无需重新配置。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 插件通过 URL 拦截实现登录地址隐藏，不会修改任何 WordPress 核心文件；<br> — 设置新登录地址后，请务必收藏或牢记新的 URL；一旦忘记，只能通过服务器文件管理删除插件来恢复默认入口；<br> — 自定义登录地址不能使用 <code>wp-login</code>、<code>wp-admin</code> 等 WordPress 保留词汇，插件会自动过滤并回退为 <code>login</code>；<br> — 与 BuddyPress 和 Buddyboss 不兼容，这两款插件有独立的 <code>wp-admin</code> 重定向机制；<br> — 登录页美化功能使用独立模板渲染，与主题的登录页定制代码互不冲突。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 作者网站：softbangong.top<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07-12" tabindex="-1">v1.0.0（2026-07-12） <a class="header-anchor" href="#v1-0-0-2026-07-12" aria-label="Permalink to &quot;v1.0.0（2026-07-12）&quot;">​</a></h3><p>— 首次发布；<br> — 支持自定义登录地址 slug，拦截并隐藏 <code>wp-admin</code> 和 <code>wp-login.php</code> 入口；<br> — 支持未登录访问后台自动重定向（可配置跳转到登录页或自定义页面）；<br> — 内置登录页自定义美化模块：主色调、背景渐变、自定义 Logo、卡片尺寸等可视化配置；<br> — 美化模板内置完整的登录、找回密码、重置密码流程，不依赖默认 <code>wp-login.php</code> 界面；<br> — 内置中英双语 PHP 翻译数组，支持自动 / 中文 / English 三种语言模式，后台实时切换；<br> — 完整适配 WordPress 多站点网络，支持网络级默认配置和各子站点独立覆盖；<br> — 多层 404 状态码修正机制（<code>parse_request</code> + <code>status_header</code> + 模板直出），确保登录页正常响应；<br> — 登录地址 slug 变更时自动刷新 Rewrite 规则；<br> — 全站 URL 过滤器自动替换 <code>wp-login.php</code> 为新地址（<code>site_url</code>、<code>wp_redirect</code>、欢迎邮件等）；<br> — 卸载时自动清理所有选项数据（含多站点各子站）。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3039.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3039.html</a></p>',53)])])}const b=o(n,[["render",t]]);export{g as __pageData,b as default};
